/**
 * Static relationship + routine metadata (generated by
 * scripts/generate-relationships.mjs) and PostgREST v12's embed resolution
 * rules (Plan.hs `findRel`, SchemaCache.hs `addInverseRels` / `addM2MRels`).
 * Nothing here queries the database at request time.
 */
import { requestError } from "./errors";

export type ForeignKeyMeta = {
	name: string;
	schema: string;
	table: string;
	columns: string[];
	refSchema: string;
	refTable: string;
	refColumns: string[];
};

export type TableMeta = {
	/** pg_class.relkind: r table, p partitioned, v view, m matview, f foreign */
	kind: string;
	primaryKey: string[];
	/** Column sets of UNIQUE constraints (and the PK), each sorted by attnum. */
	uniques: string[][];
};

export type RoutineArgMeta = { name: string; type: string; hasDefault: boolean; variadic?: boolean };

export type RoutineMeta = {
	args: RoutineArgMeta[];
	/** format_type of the return type. */
	returnType: string;
	returnsSet: boolean;
	/** composite: rows/objects; scalar: plain values; void; record: unsupported (needs a column list). */
	returnKind: "scalar" | "composite" | "void" | "record";
	/** schema.table when the function returns a table's row type (enables embedding on its result). */
	returnRelation: string | null;
	volatility: "i" | "s" | "v";
};

export type RelationshipMetadata = {
	version: 1;
	generatedAt?: string | null;
	schemas?: string[];
	tables: Record<string, TableMeta>;
	foreignKeys: ForeignKeyMeta[];
	functions: Record<string, RoutineMeta[]>;
};

export type Qualified = { schema: string; name: string };

export type Relationship = {
	cardinality: "m2o" | "o2m" | "o2o" | "m2m";
	toOne: boolean;
	isSelf: boolean;
	origin: Qualified;
	target: Qualified;
	/** FK constraint name (for m2m: the junction's FK to the origin). */
	constraint: string;
	/** (origin column, target column) join pairs for m2o / o2m / o2o. */
	columns: Array<[string, string]>;
	junction?: {
		table: Qualified;
		constraintToOrigin: string;
		constraintToTarget: string;
		/** (junction column, origin column) */
		originColumns: Array<[string, string]>;
		/** (junction column, target column) */
		targetColumns: Array<[string, string]>;
	};
};

const key = (q: Qualified) => `${q.schema}.${q.name}`;

type Index = Map<string, Relationship[]>;
const indexes = new WeakMap<RelationshipMetadata, Index>();

function sameSet(a: string[], b: string[]) {
	if (a.length !== b.length) return false;
	const s = new Set(a);
	return b.every((x) => s.has(x));
}

function buildIndex(meta: RelationshipMetadata): Index {
	const m2o: Relationship[] = [];
	for (const fk of meta.foreignKeys) {
		const origin = { schema: fk.schema, name: fk.table };
		const target = { schema: fk.refSchema, name: fk.refTable };
		const table = meta.tables[key(origin)];
		const oneToOne = !!table?.uniques.some((u) => sameSet(u, fk.columns) && u.length === fk.columns.length);
		m2o.push({
			cardinality: oneToOne ? "o2o" : "m2o",
			toOne: true,
			isSelf: key(origin) === key(target),
			origin,
			target,
			constraint: fk.name,
			columns: fk.columns.map((c, i) => [c, fk.refColumns[i]!] as [string, string]),
		});
	}
	const all: Relationship[] = [...m2o];
	// addM2MRels: a table with two different FKs whose columns are all part of its PK.
	for (const r1 of m2o) {
		if (r1.cardinality !== "m2o") continue;
		for (const r2 of m2o) {
			if (r2.cardinality !== "m2o" || key(r1.origin) !== key(r2.origin) || r1.constraint === r2.constraint) continue;
			const pk = new Set(meta.tables[key(r1.origin)]?.primaryKey ?? []);
			const cols = [...r1.columns.map((c) => c[0]), ...r2.columns.map((c) => c[0])];
			if (!pk.size || !cols.every((c) => pk.has(c))) continue;
			all.push({
				cardinality: "m2m",
				toOne: false,
				isSelf: key(r1.target) === key(r2.target),
				origin: r1.target,
				target: r2.target,
				constraint: r1.constraint,
				columns: [],
				junction: {
					table: r1.origin,
					constraintToOrigin: r1.constraint,
					constraintToTarget: r2.constraint,
					originColumns: r1.columns.map(([j, o]) => [j, o]),
					targetColumns: r2.columns.map(([j, t]) => [j, t]),
				},
			});
		}
	}
	// addInverseRels: every M2O has an O2M inverse; every O2O has an O2O inverse.
	for (const r of m2o) {
		all.push({
			cardinality: r.cardinality === "o2o" ? "o2o" : "o2m",
			toOne: r.cardinality === "o2o",
			isSelf: r.isSelf,
			origin: r.target,
			target: r.origin,
			constraint: r.constraint,
			columns: r.columns.map(([a, b]) => [b, a] as [string, string]),
		});
	}
	const index: Index = new Map();
	for (const r of all) {
		const k = key(r.origin);
		const list = index.get(k);
		if (list) list.push(r);
		else index.set(k, [r]);
	}
	return index;
}

function relationshipsFrom(meta: RelationshipMetadata, origin: Qualified): Relationship[] {
	let index = indexes.get(meta);
	if (!index) {
		index = buildIndex(meta);
		indexes.set(meta, index);
	}
	return index.get(key(origin)) ?? [];
}

const singleCol = (r: Relationship, side: 0 | 1, name: string) => r.cardinality !== "m2m" && r.columns.length === 1 && r.columns[0]![side] === name;

/**
 * Resolve `target` (with optional `!hint`) from `origin`, exactly as PostgREST
 * v12.2 `findRel` does. Throws PGRST200 (none) / PGRST201 (ambiguous).
 */
export function findRelationship(meta: RelationshipMetadata, schema: string, origin: Qualified, target: string, hint: string | null): Relationship {
	const candidates = relationshipsFrom(meta, origin).filter((r) => {
		if (r.target.schema !== schema) return false;
		if (r.junction && r.junction.table.schema !== schema) return false;
		const targetIsTable = r.target.name === target;
		if (r.isSelf) {
			if (r.cardinality === "m2m" || r.cardinality === "o2o") return false; // PostgREST: TODO, not handled
			if (hint === null) {
				return (targetIsTable && r.cardinality === "o2m") || (singleCol(r, 0, target) && r.cardinality === "m2o");
			}
			return targetIsTable && r.cardinality === "o2m" && singleCol(r, 1, hint);
		}
		if (hint === null) {
			return targetIsTable || (r.cardinality !== "m2m" && r.constraint === target) || singleCol(r, 0, target);
		}
		return (
			targetIsTable &&
			((r.cardinality !== "m2m" && r.constraint === hint) || singleCol(r, 0, hint) || singleCol(r, 1, hint) || (r.cardinality === "m2m" && r.junction!.table.name === hint))
		);
	});
	if (candidates.length === 1) return candidates[0]!;
	if (candidates.length === 0) {
		throw requestError(
			400,
			"PGRST200",
			`Could not find a relationship between '${origin.name}' and '${target}' in the schema cache`,
			`Searched for a foreign key relationship between '${origin.name}' and '${target}'${hint ? ` using the hint '${hint}'` : ""} in the schema '${schema}', but no matches were found.`,
			null,
		);
	}
	throw requestError(
		300,
		"PGRST201",
		`Could not embed because more than one relationship was found for '${origin.name}' and '${target}'`,
		candidates.map((r) => ({
			cardinality: r.cardinality === "o2o" ? "one-to-one" : r.cardinality === "m2o" ? "many-to-one" : r.cardinality === "o2m" ? "one-to-many" : "many-to-many",
			embedding: `${origin.name} with ${r.target.name}`,
			relationship: r.junction
				? `${r.junction.table.name} using ${r.junction.constraintToOrigin}(${r.junction.originColumns.map((c) => c[0]).join(", ")}) and ${r.junction.constraintToTarget}(${r.junction.targetColumns.map((c) => c[0]).join(", ")})`
				: `${r.constraint} using ${r.cardinality === "o2m" ? r.target.name : r.origin.name}(${r.columns.map((c) => (r.cardinality === "o2m" ? c[1] : c[0])).join(", ")}) and ${r.cardinality === "o2m" ? r.origin.name : r.target.name}(${r.columns.map((c) => (r.cardinality === "o2m" ? c[0] : c[1])).join(", ")})`,
		})),
		`Try changing '${target}' to one of the following: ${candidates.map((r) => `'${target}!${r.junction ? r.junction.table.name : r.constraint}'`).join(", ")}. Find the desired relationship in the 'details' key.`,
	);
}

export function tableMeta(meta: RelationshipMetadata, q: Qualified): TableMeta | undefined {
	return meta.tables[key(q)];
}

export function routineOverloads(meta: RelationshipMetadata, schema: string, name: string): RoutineMeta[] {
	return meta.functions[`${schema}.${name}`] ?? [];
}

export const EMPTY_METADATA: RelationshipMetadata = { version: 1, generatedAt: null, tables: {}, foreignKeys: [], functions: {} };
